public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        int numCourses = Integer.parseInt(sc.nextLine().trim());
        if (!sc.hasNextLine()) return;
        String line = sc.nextLine().trim();

        int[] inDegree = new int[numCourses];
        Map<Integer, List<Integer>> adj = new HashMap<>();

        // Parse [[1,0],[0,1]] format
        if (!line.equals("[]") && line.length() > 2) {
            // Remove outer brackets
            String inner = line.substring(1, line.length() - 1);
            // Find all [a,b] pairs
            int i = 0;
            while (i < inner.length()) {
                if (inner.charAt(i) == '[') {
                    int j = inner.indexOf(']', i);
                    String pair = inner.substring(i + 1, j);
                    String[] parts = pair.split(",");
                    int a = Integer.parseInt(parts[0].trim());
                    int b = Integer.parseInt(parts[1].trim());
                    adj.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
                    inDegree[a]++;
                    i = j + 1;
                } else {
                    i++;
                }
            }
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < numCourses; i++) {
            if (inDegree[i] == 0) queue.offer(i);
        }

        int count = 0;
        while (!queue.isEmpty()) {
            int curr = queue.poll();
            count++;
            if (adj.containsKey(curr)) {
                for (int nb : adj.get(curr)) {
                    if (--inDegree[nb] == 0) queue.offer(nb);
                }
            }
        }
        System.out.println(count == numCourses ? "True" : "False");
    }
}

