import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String line = sc.nextLine().trim();
        String content = line.substring(1, line.length() - 1).trim();
        String[] rowsRaw = content.split("\\],\\s*\\[");
        int R = rowsRaw.length;
        int C = rowsRaw[0].replace("[", "").replace("]", "").split(",").length;
        int[][] grid = new int[R][C];
        Queue<int[]> q = new LinkedList<>();
        int fresh = 0;
        for (int i = 0; i < R; i++) {
            String[] cells = rowsRaw[i].replace("[", "").replace("]", "").split(",");
            for (int j = 0; j < C; j++) {
                grid[i][j] = Integer.parseInt(cells[j].trim());
                if (grid[i][j] == 2) q.offer(new int[]{i, j});
                else if (grid[i][j] == 1) fresh++;
            }
        }

        if (fresh == 0) { System.out.println(0); return; }
        int minutes = -1;
        int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        while (!q.isEmpty()) {
            minutes++;
            int size = q.size();
            for (int k = 0; k < size; k++) {
                int[] curr = q.poll();
                for (int[] d : dirs) {
                    int ni = curr[0] + d[0], nj = curr[1] + d[1];
                    if (ni >= 0 && ni < R && nj >= 0 && nj < C && grid[ni][nj] == 1) {
                        grid[ni][nj] = 2;
                        fresh--;
                        q.offer(new int[]{ni, nj});
                    }
                }
            }
        }
        System.out.println(fresh == 0 ? minutes : -1);
    }
}

